SourceCode.Declaration:
internal class GUPListSorter
{
    private static GUPListSorter listSorter = new GUPListSorter();

}

Method.Source:
public static GUPListSorter getInstance()
{
    return listSorter;
}

public List sortList(List _list, GUPIComparator _comparator)
{
    Array toSort = new Array(Types::AnyType);

    int i = 1;
    ListEnumerator enumerator = _list.getEnumerator();
    while (enumerator.moveNext())
    {
        toSort.value(i, enumerator.current());
        i++;
    }

    toSort = this.sortArray(toSort, _comparator);

    List sortedList = new List(Types::AnyType);
    for (int j = 1; j <= toSort.lastIndex(); j++)
    {
        sortedList.addEnd(toSort.value(j));
    }
    return sortedList;
}

public Array sortArray(Array _toSort, GUPIComparator _comparator)
{
    this.quickSort(_toSort, 1, _toSort.lastIndex(), _comparator);
    return _toSort;
}

private void quicksort(Array _toSort, int _leftIndex, int _rightIndex, GUPIComparator _comparator)
{
    if (_leftIndex < _rightIndex)
    {
        int partitionIndex = this.partition(_toSort, _leftIndex, _rightIndex, _comparator);
        this.quicksort(_toSort, _leftIndex, partitionIndex - 1, _comparator);
        this.quicksort(_toSort, partitionIndex + 1, _rightIndex, _comparator);
    }
}

private int partition(Array _toSort, int _leftIndex, int _rightIndex, GUPIComparator _comparator)
{
    int pivot = _leftIndex;
    int swapIndex = _leftIndex + 1;

    for (int i = swapIndex; i <= _rightIndex; i++)
    {
        if (_comparator.compare(_toSort.value(i), _toSort.value(pivot)) < 0)
        {
            this.swap(_toSort, i, swapIndex);
            swapIndex ++;
        }
    }

    this.swap(_toSort, pivot, swapIndex - 1);
    return swapIndex - 1;
}

private void swap(Array _toSort, int swapFrom, int swapTo)
{
    anytype val = _toSort.value(swapFrom);
    _toSort.value(swapFrom, _toSort.value(swapTo));
    _toSort.value(swapTo, val);
}
